import type Device from '../lib/Device';
export type OnEventEvent = {
    args: {
        signalId: string;
        frequency: string;
        event: 'payload';
        args: [Array<number>, boolean];
    };
    return: void;
};
export type TxEvent = {
    args: {
        signalId: string;
        frequency: string;
        frame: Array<number> | Buffer;
        opts?: {
            repetitions?: number;
            device?: Device;
        };
    };
    return: void;
};
export type CmdEvent = {
    args: {
        signalId: string;
        frequency: string;
        commandId: string;
        opts?: {
            repetitions?: number;
            device?: Device;
        };
    };
    return: void;
};
export type EnableEvent = {
    args: {
        signalId: string;
        frequency: string;
    };
    return: void;
};
export type DisableEvent = {
    args: {
        signalId: string;
        frequency: string;
    };
    return: void;
};
export type HomeyRFEvents = {
    onEvent: OnEventEvent;
};
export type SDKRFEvents = {
    tx: TxEvent;
    cmd: CmdEvent;
    enable: EnableEvent;
    disable: DisableEvent;
};
